selected.compute:
pool = read('/input/options')
result = None
existing = read('/output/selection')
if existing is not None and valid(existing):
    result = existing
else:
    for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
        for group in combinations(pool, count):
            proposal = [entry['id'] for entry in group]
            if valid(proposal):
                result = proposal
                break
        if result is not None:
            break

selected.effects:
receipt_state = receipt('report')
if receipt_state == 'unknown':
    delivery_state = status('report')
else:
    delivery_state = receipt_state
if delivery_state == 'sent' or delivery_state == 'success':
    delivered = True
elif delivery_state == 'not_sent' or delivery_state == 'unattempted':
    delivered = False
else:
    delivered = None
if delivered == False and result is not None:
    if exists('/output/selection'):
        output_value = read('/output/selection')
    else:
        write('/output/selection', result)
        output_value = result
    send('report', 'team', output_value)
if exists('/tmp/cache'):
    delete('/tmp/cache')
